    int64_t* sieve_interval= (int64_t*)malloc(n*sizeof(int64_t));

    for(int64_t i=2; i<n; ++i){

      if(i<30) continue;
      sieve_interval[i]=i;

    };

    printf("Intervalo original: ");
    for(int64_t i=2; i<n; ++i){
      if(sieve_interval[i]>0) printf("%li, ", sieve_interval[i]);      
