scanf("%lu", &number);
printf("Digite um número inteiro (expoente): ");
scanf("%lu", &power);
//Exibindo o resultado da soma
printf("1^%lu+2^%lu+...+%lu^%lu = %lu\n", power, power, number, power, faulhaber_formula(number, power));

//Finalizando a aplicação
return 0;
          }

