javascript:(function(){
/* Generate a new Excalidraw drawing by crafting a random url, along with a throwaway QSP to allow bookmarking in Raindrop.io etc */

    /* Generate random hex string of specified length */
    function randomHex(length){
        return Array.from(crypto.getRandomValues(new Uint8Array(length))).map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,length);
    }

    /* Generate random base64-like string of specified length */
    function randomBase64(length){
        return btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(Math.ceil(length * 3/4)))))
            .replace(/[+/]/g, c => c === '+' ? '-' : '_')
            .substring(0, length);
    }

    /* Generate room ID and secret */
    const roomId = randomHex(16);
    const secret = randomBase64(22);

    /* Get current timestamp */
    const timestamp = Date.now();

    /* Open new Excalidraw window with room ID, secret, and timestamp */
    window.open(`https://excalidraw.com/?_=${timestamp}#room=${roomId},${secret}`, '_blank');
})();

javascript:(function() {
  let collectedTweets = new Set();

  function collectData() {
    document.querySelectorAll('article').forEach(article => {
      const tweetDiv = article.querySelector('div[data-testid="tweetText"]');
      const popularityDiv = article.querySelector('div[role="group"]');
      if (tweetDiv && popularityDiv) {
        const tweetText = tweetDiv.innerText.trim();
        const popularityData = popularityDiv.ariaLabel ? popularityDiv.ariaLabel.trim() : 'No popularity data';
        const tweetData = `${tweetText} - ${popularityData}`;
        collectedTweets.add(tweetData);
      }
    });
  }

  function scrollAndCollect() {
    collectData();
    window.scrollBy(0, window.innerHeight);
    if ((window.innerHeight + window.pageYOffset) < document.body.scrollHeight) {
      setTimeout(scrollAndCollect, 200);
    } else {
      const newWindow = window.open("", "_blank");
      newWindow.document.write("<pre>" + Array.from(collectedTweets).join("\n\n") + "</pre>");
    }
  }

  scrollAndCollect();
})();

javascript:(function(){ /* Gets parameters from Google Maps and opens in Google Earth */
    var mapsUrl = window.location.href;
    var coordsMatch = mapsUrl.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
    var searchTermMatch = mapsUrl.match(/place\/([^\/]+)\//);

    if (coordsMatch) {
        var lat = coordsMatch[1];
        var lng = coordsMatch[2];
        var searchTerm = searchTermMatch ? decodeURIComponent(searchTermMatch[1].replace(/\+/g, ' ')) : '';
        var earthUrl = "https://earth.google.com/web/search/"+searchTerm+"/@"+lat+","+lng+",0a,100000d,0y,0h,60t,0r";
        window.open(earthUrl, '_blank');
    } else {
        alert("Could not find coordinates in the URL");
    }
})();

