#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <poll.h>
#include "common.h"

struct FDmsg
{
	int msg;
	FD *fd;
};

static FD *fds[100];
static struct pollfd pfds[100];
static int nfds;
static int pollpipe[2] = { -1, -1 };

static void
removeslot(int i)
{
	pfds[i].revents = 0;
	pfds[i].events = 0;
	pfds[i].fd = -1;
	fds[i]->fd = -1;
	fds[i]->id = -1;
	fds[i]->ready = 0;
	fds[i] = nil;
}

static void
pollfds(void)
{
	struct FDmsg msg;
	FD *fd;
	int i, n;

	pipe(pollpipe);
	pfds[0].fd = pollpipe[0];
	pfds[0].events = POLLIN;
	nfds = 1;
	for(;;) {
		n = poll(pfds, nfds, -1);
		if(n < 0) {
			perror("error poll");
			return;
		}

		/* someone wants us to watch their fd or has closed it */
		if(pfds[0].revents & POLLIN) {
			read(pfds[0].fd, &msg, sizeof(msg));
			fd = msg.fd;
			switch(msg.msg) {
			// wait
			case 1:
				if(fd->id >= 0) {
					/* already in list */
					assert(fds[fd->id] == fd);
//printf("polling fd %d in slot %d\n", fd->fd, fd->id);
				} else {
					/* add to list */
					for(i = 1; i < nfds; i++)
						if(fds[i] == nil)
							break;
					assert(i < nelem(pfds));
					if(i == nfds) nfds++;
					fd->id = i;
					fds[fd->id] = fd;
//printf("adding fd %d in slot %d\n", fd->fd, fd->id);
				}
				pfds[fd->id].fd = fd->fd;
				pfds[fd->id].events = POLLIN;
				pfds[fd->id].revents = 0;
				fd->ready = 0;
				break;

			// close
			case 2:
				/* fd was closed */
//printf("received close for fd %d slot %d\n", pfds[fd->id].fd, fd->id);
				assert(fd->id >= 0);
				close(pfds[fd->id].fd);
				removeslot(fd->id);
				break;
			}
		}

		for(i = 1; i < nfds; i++) {
			/* fd was closed on other side */
			if(pfds[i].revents & POLLHUP) {
//printf("fd %d hung up\n", pfds[i].fd);
				close(fds[i]->fd);
				removeslot(i);
			}
			if(pfds[i].revents & POLLIN) {
//printf("fd %d became ready\n", pfds[i].fd);
				/* ignore this fd for now */
				pfds[i].fd = -1;
				pfds[i].events = 0;
				pfds[i].revents = 0;
				fds[i]->ready = 1;
			}
			if(pfds[i].revents)
				printf("more events on fd %d: %d\n", pfds[i].fd, pfds[i].revents);
		}
	}
}

static void *pollthread(void *arg) { pollfds(); return nil; }

void
startpolling(void)
{
	pthread_t th;
	pthread_create(&th, nil, pollthread, nil);

	// wait for thread to start so waitfd can do its thing
	while(((volatile int*)pollpipe)[0] < 0) usleep(1000);
}

void
waitfd(FD *fd)
{
	struct FDmsg msg;
	if(fd->fd < 0)
		return;
	fd->ready = 0;
	msg.msg = 1;
	msg.fd = fd;
	write(pollpipe[1], &msg, sizeof(msg));
}

void
closefd(FD *fd)
{
	struct FDmsg msg;
	printf("closing fd %d\n", fd->fd);
	int i = fd->id;
	msg.msg = 2;
	msg.fd = fd;
	write(pollpipe[1], &msg, sizeof(msg));
	// wait for thread to notice
	while(((volatile FD**)fds)[i] != nil) usleep(1);
}

from memory import Memory
import time

def get_target(dict:dict) -> tuple:
    angle = False
    move = False
    try:
        if dict["angle"] != 0 or dict["distance"] != 0 :
            print(str(dict))
            angle = dict["angle"]
            move = dict["distance"]
    except KeyError:
        pass
    return angle, move

def check_targets() -> tuple:
    angle = False
    move = False
    source = ""
    target_dict = mem.retrieveLastSensorReading("follow")
    person_dict = mem.retrieveLastSensorReading("person")
    if any((get_target(target_dict))):
        angle, move = get_target(target_dict)
        print("Legs:", angle, move)
    elif any((get_target(person_dict))):
        angle, move = get_target(person_dict)
        print("Person:", angle, move)
    else:
        target_dicts = mem.retrieveSensorReadings("follow")
        for target_dict in target_dicts:
            if any((get_target(target_dict))):
                angle, move = get_target(target_dict)
                age = target_dict["time"] - time.time()
                print(age,"s - old legs:", angle, move)
                break
    return angle, move

mem = Memory()
while True:
    time.sleep(1)
    angle = 0
    move = 0
    angle, move = check_targets()
    # move if the angle or distance is not zero
    if angle != 0 or move !=0:
        print("Target dir:", angle, "dist:", move)
        damp_angle = 3.0
        damp_distance = 2.0
        if abs(angle) >= (0.1 * damp_angle) :
            if mem.retrieveState("rotate") > 0.0:
                print("Turning: ",str(angle / damp_angle))
            else:
                print("Turn blocked")
                time.sleep(3.0)
        else:
            if abs(move) >= (0.05 * damp_distance) :
                distance = move / damp_distance
                safe_forward = mem.retrieveState("forward")
                safe_backward = mem.retrieveState("reverse")
                # nb should also retrieve a backward state
                if distance >= 0:
                    if  safe_forward > distance:
                        print("Moving forward detected distance:", str(distance))
                    else:
                        print("Moving forward safe distance:", str(safe_forward))
                else:
                    if safe_backward < distance:
                        print("Moving backward detected distance:", str(distance))
                    else:
                        print("Moving backward safe distance:", str(safe_backward))
    else:
        print("Nothing detected, not moving")

