    if (!Fs.existsSync(newPath)) {
        throw new Error("File path mismatch: " + newPath);
    }
    if (!Fs.existsSync(oldPath)) {
        throw new Error("File path mismatch: " + oldPath);
    }
    const from = REVERSE ? oldPath : newPath;
    const to = REVERSE ? newPath : oldPath;
    Fs.cpSync(from, to);
});

